import json, sys, re
import statistics
data = json.loads(sys.stdin.read())
result = json.loads(data['result'])
experiments = result['data']['experiments']

# Group obs_only K=10 by epsilon
eps_groups = {}
for exp_id, exp in experiments.items():
    name = exp_id.lower()
    if 'obs' in name and 'only' in name and 'object' in name and exp.get('conclusion') == 'success' and 'k5' not in name and 'k1' not in name and 'k20' not in name:
        metrics = exp.get('metrics', {})
        sr = metrics.get('success_rate', metrics.get('overall_success_rate', metrics.get('overall_sr', None)))
        if sr is None:
            continue
        try:
            sr = float(str(sr).replace('%', '').strip().split()[0])
        except:
            continue
        if sr > 1:
            sr = sr / 100.0

        # Extract epsilon
        eps_match = re.search(r'norm([\d]+)', exp_id)
        if eps_match:
            eps_raw = eps_match.group(1)
            if eps_raw == '003':
                eps = 0.03
            elif eps_raw == '005':
                eps = 0.05
            elif eps_raw == '01':
                eps = 0.1
            elif eps_raw == '02':
                eps = 0.2
            elif eps_raw == '03':
                eps = 0.3
            else:
                eps = float('0.' + eps_raw)
        elif 'default' in exp_id:
            eps = 'default'
        else:
            continue

        if eps not in eps_groups:
            eps_groups[eps] = []
        eps_groups[eps].append((sr, exp_id))

# Print summary
print('=== obs_only K=10 by epsilon (Object) ===')
for eps in sorted([e for e in eps_groups if e != 'default']):
    srs = [s[0] for s in eps_groups[eps]]
    mean = statistics.mean(srs)
    std = statistics.stdev(srs) if len(srs) > 1 else 0
    print(f'  eps={eps}: n={len(srs)}, mean={mean*100:.1f}% +/- {std*100:.1f}%')
    for sr, eid in sorted(eps_groups[eps]):
        print(f'    {sr*100:.0f}% - {eid}')

if 'default' in eps_groups:
    srs = [s[0] for s in eps_groups['default']]
    mean = statistics.mean(srs)
    std = statistics.stdev(srs) if len(srs) > 1 else 0
    print(f'  eps=default(uncapped): n={len(srs)}, mean={mean*100:.1f}% +/- {std*100:.1f}%')
